    float c[BLOCK_ROWS][BLOCK_ROWS] = {{0}};

    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        int tile_offset = tile * TILE_SIZE;

        // Load tile of A into shared memory
        int A_row = block_row + thread_row;
        int A_col = tile_offset + thread_col;
        if (A_row < N && A_col < N) {
            A_tile[thread_row][thread_col] = A[A_row * N + A_col];
        } else {
            A_tile[thread_row][thread_col] = 0.0f;
